<?php
/** ImageGrid rendering tab. @package MillionDollarScript\Extensions\ImageGrid */
if (!defined('ABSPATH')) {
    exit;
}
$show_render_disabled_reason = !empty($render_disabled_reason) && $render_disabled_reason !== $notice_message;
$show_selected_last_error = !empty($selected_last_error) && $selected_last_error !== $notice_message && (!$authorization_required || $selected_last_error !== $render_disabled_reason);
?>
<section class="mds-imagegrid-panel">
    <div class="mds-imagegrid-panel-header"><div><h2><?php esc_html_e('Rendering behavior', 'mds-imagegrid'); ?></h2><p class="description"><?php esc_html_e('Choose when eligible grids are sent to ImageGrid and when smaller grids remain on this WordPress server.', 'mds-imagegrid'); ?></p></div></div>
    <form class="mds-imagegrid-settings-form mds-imagegrid-narrow-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
        <?php wp_nonce_field('mds_imagegrid_save_settings'); ?><input type="hidden" name="action" value="mds_imagegrid_save_settings"><input type="hidden" name="section" value="rendering">
        <?php
        self::checkbox_field('mds_imagegrid_enabled', __('Enable ImageGrid', 'mds-imagegrid'), $enabled, __('Allow eligible large-grid render jobs to use the connected ImageGrid account.', 'mds-imagegrid'));
        self::checkbox_field('mds_imagegrid_auto_render', __('Automatic rendering', 'mds-imagegrid'), $auto_render, __('Submit eligible jobs automatically. Remote jobs can consume processing credits and count toward account plan limits.', 'mds-imagegrid'), __('When disabled, an administrator must submit remote renders manually. Grids that are too large for local rendering may remain unavailable until that happens.', 'mds-imagegrid'));
        self::checkbox_field('mds_imagegrid_failure_email_enabled', __('Render failure email', 'mds-imagegrid'), $failure_email_enabled, __('Email the site administrator once when a grid cannot complete ImageGrid rendering. Notices remain available in WordPress even when email is off.', 'mds-imagegrid'), __('Uses WordPress wp_mail() and the Administration Email Address from Settings > General. Repeated failures are deduplicated until the grid recovers.', 'mds-imagegrid'));
        self::input_field('mds_imagegrid_local_render_threshold_megapixels', __('Local render threshold MP', 'mds-imagegrid'), 'number', (string) $threshold, __('Render at or below this grid size in WordPress. Eligible larger grids can use ImageGrid.', 'mds-imagegrid'), '', __('Lower this value on shared hosts with limited memory or execution time. This threshold does not change the ImageGrid plan.', 'mds-imagegrid'));
        ?>
        <?php if (!$auto_render) : ?><div class="mds-imagegrid-callout mds-imagegrid-callout-warning" role="note"><strong><?php esc_html_e('Automatic rendering is off.', 'mds-imagegrid'); ?></strong> <?php esc_html_e('Large grids may require a manual render submission when local resources are insufficient.', 'mds-imagegrid'); ?></div><?php endif; ?>
        <p class="submit mds-imagegrid-settings-actions"><button type="submit" class="button button-primary"><?php esc_html_e('Save rendering settings', 'mds-imagegrid'); ?></button></p>
    </form>
</section>

<section class="mds-imagegrid-panel mds-imagegrid-grid-panel">
    <div class="mds-imagegrid-panel-header"><div><h2><?php esc_html_e('Render a grid', 'mds-imagegrid'); ?></h2><p class="description"><?php esc_html_e('Submit a specific grid and refresh its latest ImageGrid job state.', 'mds-imagegrid'); ?></p></div><?php if ($selected_grid_id && !empty($selected_state['status'])) : ?><span class="mds-imagegrid-status"><?php echo esc_html($selected_state['status']); ?></span><?php endif; ?></div>
    <?php if (empty($grids)) : ?><p><?php esc_html_e('No Million Dollar Script grids were found yet.', 'mds-imagegrid'); ?></p><?php else : ?>
        <form method="get" class="mds-imagegrid-grid-select"><input type="hidden" name="page" value="<?php echo esc_attr($page_slug); ?>"><input type="hidden" name="section" value="rendering"><label for="mds_imagegrid_grid_id"><?php esc_html_e('Grid', 'mds-imagegrid'); ?></label><select id="mds_imagegrid_grid_id" name="grid_id" onchange="this.form.submit()">
            <?php foreach ($grids as $grid) : $grid_id = \MillionDollarScript\Extensions\ImageGrid\Admin::grid_id($grid); if (!$grid_id) { continue; } $grid_title = \MillionDollarScript\Extensions\ImageGrid\Admin::grid_title($grid); ?><option value="<?php echo esc_attr($grid_id); ?>" <?php selected($selected_grid_id, $grid_id); ?>><?php echo esc_html(sprintf('%s (#%d)', $grid_title ?: __('Untitled grid', 'mds-imagegrid'), $grid_id)); ?></option><?php endforeach; ?>
        </select><noscript><button class="button" type="submit"><?php esc_html_e('Choose grid', 'mds-imagegrid'); ?></button></noscript></form>
        <?php if ($show_render_disabled_reason) : ?><p class="mds-imagegrid-callout mds-imagegrid-callout-warning"><?php echo esc_html($render_disabled_reason); ?> <a href="<?php echo esc_url($section_urls['connection']); ?>"><?php esc_html_e('Review connection', 'mds-imagegrid'); ?></a></p><?php elseif (!$cdn_known) : ?><p class="description mds-imagegrid-render-help"><?php esc_html_e('Refresh account status before relying on CDN delivery.', 'mds-imagegrid'); ?></p><?php elseif (!$cdn_access) : ?><p class="description mds-imagegrid-render-help"><?php esc_html_e('Hosted rendering is available, but public tile delivery remains local because CDN Delivery is not active.', 'mds-imagegrid'); ?></p><?php endif; ?>
        <div class="mds-imagegrid-grid-actions"><?php self::grid_action_form('mds_imagegrid_submit_grid_render', 'mds_imagegrid_submit_grid_render', $selected_grid_id, __('Render with ImageGrid', 'mds-imagegrid'), 'button button-primary', !empty($render_disabled), $render_disabled_reason, ''); self::grid_action_form('mds_imagegrid_refresh_job', 'mds_imagegrid_refresh_job', $selected_grid_id, __('Refresh job', 'mds-imagegrid'), 'button', !$selected_grid_id || empty($selected_state['job_id']), '', ''); ?></div>
        <dl class="mds-imagegrid-facts mds-imagegrid-grid-state"><?php $preflight = isset($selected_state['preflight']) && is_array($selected_state['preflight']) ? $selected_state['preflight'] : []; $preflight_label = isset($preflight['ok']) ? ($preflight['ok'] ? __('Ready', 'mds-imagegrid') : __('Failed', 'mds-imagegrid')) : __('Not run', 'mds-imagegrid'); self::fact(__('State', 'mds-imagegrid'), $selected_state['status'] ?? __('None', 'mds-imagegrid')); self::fact(__('Job ID', 'mds-imagegrid'), $selected_state['job_id'] ?? __('None', 'mds-imagegrid')); self::fact(__('Tileset ID', 'mds-imagegrid'), $selected_state['tileset_id'] ?? __('None', 'mds-imagegrid')); self::fact(__('Tiles', 'mds-imagegrid'), !empty($selected_state['total_tiles']) ? number_format_i18n((int) $selected_state['total_tiles']) : __('Unknown', 'mds-imagegrid')); self::fact(__('CDN Delivery', 'mds-imagegrid'), $cdn_access ? __('Enabled', 'mds-imagegrid') : ($cdn_known ? __('Local fallback', 'mds-imagegrid') : __('Unknown', 'mds-imagegrid'))); self::fact(__('Submission check', 'mds-imagegrid'), $preflight_label); self::fact(__('Updated', 'mds-imagegrid'), $selected_state['updated_at'] ?? __('Never', 'mds-imagegrid')); ?></dl>
        <?php if ($show_selected_last_error) : ?><p class="mds-imagegrid-error"><?php echo esc_html($selected_last_error); ?></p><?php endif; ?>
    <?php endif; ?>
</section>
